{"files":[{"path":"daily_net.py","content":"import csv
import sys
import os
from decimal import Decimal, InvalidOperation
from datetime import datetime

REQUIRED = ["paid_at", "channel", "status", "amount", "refund_amount"]
VALID_STATUS = {"PAID", "REFUNDED", "CANCELLED"}


def fail(msg):
    sys.stderr.write(msg + "\n")
    sys.exit(2)


def parse_amount(s, rowno, field):
    t = s.strip()
    if t == "":
        fail(f"row {rowno}: {field}: empty amount")
    try:
        d = Decimal(t)
    except InvalidOperation:
        fail(f"row {rowno}: {field}: invalid decimal")
    if not d.is_finite():
        fail(f"row {rowno}: {field}: NaN or infinite")
    if d < 0:
        fail(f"row {rowno}: {field}: negative")
    exp = d.as_tuple().exponent
    if exp < -2:
        fail(f"row {rowno}: {field}: more than two decimal places")
    return d


def main():
    if len(sys.argv) != 3:
        sys.stderr.write("usage: python daily_net.py input.csv output.csv\n")
        sys.exit(2)
    in_path, out_path = sys.argv[1], sys.argv[2]
    if os.path.abspath(in_path) == os.path.abspath(out_path):
        fail("input and output paths are the same")

    try:
        f = open(in_path, "r", encoding="utf-8-sig", newline="")
    except OSError as e:
        fail(f"cannot open input: {e}")

    totals = {}
    with f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            fail("missing header")
        header = [h.strip() for h in header]
        idx = {}
        for name in REQUIRED:
            if name not in header:
                fail(f"missing required field: {name}")
            idx[name] = header.index(name)

        rowno = 0
        for row in reader:
            rowno += 1
            if len(row) == 0:
                continue
            if len(row) < len(header):
                row = row + [""] * (len(header) - len(row))

            status = row[idx["status"]].strip()
            if status not in VALID_STATUS:
                fail(f"row {rowno}: status: unknown status {status!r}")
            if status == "CANCELLED":
                continue

            paid_at = row[idx["paid_at"]].strip()
            try:
                datetime.strptime(paid_at, "%Y-%m-%d")
                if len(paid_at) != 10:
                    raise ValueError
            except ValueError:
                fail(f"row {rowno}: paid_at: invalid date")

            channel = row[idx["channel"]].strip()
            if channel == "":
                fail(f"row {rowno}: channel: empty")

            amount = parse_amount(row[idx["amount"]], rowno, "amount")
            refund = parse_amount(row[idx["refund_amount"]], rowno, "refund_amount")
            if refund > amount:
                fail(f"row {rowno}: refund_amount: greater than amount")

            net = amount - refund
            key = (paid_at, channel)
            totals[key] = totals.get(key, Decimal("0")) + net

    lines = ["date,channel,net_amount"]
    for (date, channel) in sorted(totals.keys()):
        val = totals[(date, channel)]
        lines.append(f"{date},{channel},{val:.2f}")
    content = "\n".join(lines) + "\n"

    tmp = out_path + ".tmp"
    try:
        with open(tmp, "w", encoding="utf-8", newline="") as of:
            of.write(content)
        os.replace(tmp, out_path)
    except OSError as e:
        try:
            if os.path.exists(tmp):
                os.remove(tmp)
        except OSError:
            pass
        fail(f"cannot write output: {e}")


if __name__ == "__main__":
    main()
